// Run after changing the locked development dependencies. The extension runs offline.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const packages = [
  ['@mozilla/readability', 'Readability.js', 'LICENSE.md'],
  ['turndown', 'dist/turndown.js', 'LICENSE'],
  ['turndown-plugin-gfm', 'dist/turndown-plugin-gfm.js', 'LICENSE']
];
const chunks = [
  '// Generated by scripts/vendor-clipper.cjs from package-lock.json.',
  '(() => {',
  'if (globalThis.MemosClipTools) return;'
];
for (const [name, source, license] of packages) {
  const dir = path.join(root, 'node_modules', name);
  chunks.push('/* ' + name + '\n' + fs.readFileSync(path.join(dir, license), 'utf8').replaceAll('*/', '* /') + '\n*/');
  chunks.push(fs.readFileSync(path.join(dir, source), 'utf8'));
}
chunks.push('globalThis.MemosClipTools = { Readability, TurndownService, gfm: turndownPluginGfm.gfm };', '})();', '');
const output = path.join(root, 'js/vendor/clipper-libraries.js');
fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, chunks.join('\n').replaceAll('\r\n', '\n'));
